import{_ as o,o as a,c as r,a5 as d}from"./chunks/framework.BEZBAInb.js";const h=JSON.parse('{"title":"Logger","description":"","frontmatter":{"title":"Logger","order":4},"headers":[],"relativePath":"ja/latest/tutorial/core/logger.md","filePath":"ja/latest/tutorial/core/logger.md","lastUpdated":1788455378000}'),t={name:"ja/latest/tutorial/core/logger.md"};function c(l,e,n,i,g,s){return a(),r("div",null,[...e[0]||(e[0]=[d('<h1 id="ロガー-konadologger" tabindex="-1">ロガー KonadoLogger <a class="header-anchor" href="#ロガー-konadologger" aria-label="Permalink to &quot;ロガー KonadoLogger&quot;">​</a></h1><h2 id="はじめに" tabindex="-1">はじめに <a class="header-anchor" href="#はじめに" aria-label="Permalink to &quot;はじめに&quot;">​</a></h2><p>KonadoLogger は Godot Logger の実装を基にしたログモジュールです。ログレベル、ログ形式、ログ出力、ログファイルなどをサポートし、Konado 実行時のログ情報を記録するために使用します。</p><h2 id="ログパス" tabindex="-1">ログパス <a class="header-anchor" href="#ログパス" aria-label="Permalink to &quot;ログパス&quot;">​</a></h2><p>ログファイルの論理パスは <code>user://konado_log.log</code> です。実際のディレクトリは現在の OS とプロジェクト名に応じて Godot が解決し、<code>OS.get_user_data_dir()</code> で確認できます。<code>LOG_FILE_PATH</code> は組み込み定数のため、保存先を変更する場合はカスタム版プラグインでこの定数を管理してください。</p><h2 id="画面オーバーレイログ" tabindex="-1">画面オーバーレイログ <a class="header-anchor" href="#画面オーバーレイログ" aria-label="Permalink to &quot;画面オーバーレイログ&quot;">​</a></h2><p>エラー発生時、会話シーンは画面上にログウィンドウを重ねて表示し、エラー情報を示してゲーム実行を中断します。通常の警告は引き続きログファイルに記録されますが、実行時エラーとして表示されたり、ゲームを中断したりすることはありません。エラーオーバーレイを無効にする場合は、<code>KonadoDialogueManager</code> の <code>enable_overlay_log</code> プロパティを <code>false</code> に設定してください。</p><h2 id="ログコールバック" tabindex="-1">ログコールバック <a class="header-anchor" href="#ログコールバック" aria-label="Permalink to &quot;ログコールバック&quot;">​</a></h2><p><code>KonadoLogger</code> のインスタンスは <code>error_caught(msg)</code> と <code>message_caught(message, error)</code> シグナルを送出します。<code>KonadoDialogueManager</code> はシーンツリーに入ると内部ロガーを作成して Godot に登録し、<code>error_caught</code> で画面オーバーレイを制御します。ロガーはグローバルな自動読み込みではありません。別の <code>KonadoLogger</code> を作成するカスタム連携では <code>OS.add_logger()</code> で登録し、解放前に <code>OS.remove_logger()</code> を呼び出して、重複記録や無効なインスタンスの残留を防いでください。</p><h2 id="実行時エラー" tabindex="-1">実行時エラー <a class="header-anchor" href="#実行時エラー" aria-label="Permalink to &quot;実行時エラー&quot;">​</a></h2><p>アトミック命令が失敗すると、<code>KonadoDialogueManager</code> は最終エラーを 1 件だけ記録し、<code>runtime_failure_reported(failure)</code> シグナルを送出します。<code>failure</code> には安定したエラーコード、操作、関連リソース、根本原因、ソースパスと行、命令 ID、オペコード、プログラム位置が含まれ、クラッシュレポートや独自デバッグ UI に利用できます。簡易インターフェースとして <code>runtime_failed(message, instruction_id, source_line)</code> も引き続き利用できます。</p>',11)])])}const u=o(t,[["render",c]]);export{h as __pageData,u as default};
